!function(e){function r(r){for(var t,i,o=r[0],p=r[1],d=r[2],s=0,y=[];s<o.length;s++)i=o[s],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&y.push(n[i][0]),n[i]=0;for(t in p)Object.prototype.hasOwnProperty.call(p,t)&&(e[t]=p[t]);for(g&&g(r);y.length;)y.shift()();return m.push.apply(m,d||[]),a()}function a(){for(var e,r=0;r<m.length;r++){for(var a,i=m[r],o=!0,p=1;p<i.length;p++)a=i[p],0!==n[a]&&(o=!1);o&&(m.splice(r--,1),e=t(t.s=i[0]))}return e}function t(r){if(i[r])return i[r].exports;var a=i[r]={i:r,l:!1,exports:{}};return e[r].call(a.exports,a,a.exports,t),a.l=!0,a.exports}var i={},n={62:0},m=[];t.m=e,t.c=i,t.d=function(e,r,a){t.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:a})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,r){if(1&r&&(e=t(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var a=Object.create(null);if(t.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var i in e)t.d(a,i,function(r){return e[r]}.bind(null,i));return a},t.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(r,"a",r),r},t.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=r,o=o.slice();for(var d=0;d<o.length;d++)r(o[d]);var g=p;m.push([44,0]),a()}({44:function(e,r,a){"use strict";a.r(r);var t=a(0);Object(t.a)("de","army",a(45),a(1))},45:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克歼击车","link":"de_army#de_army_tankdestroyer"}],"model":"“猎豹”重型坦克歼击车","description":"<p>猎豹重型坦克歼击车是在豹式中型坦克的底盘上，装上1门Pak43型71倍径88mm火炮，在1944年2月开始投产的又一种自行反坦克炮车，该车至1945德军投降时，总共生产了392辆。最早装备猎豹重型坦克歼击车的是德军的654重型坦克歼击车营，后又陆续装备了519、559等混编的重型坦克歼击车营。</p><p>猎豹重型坦克歼击车的战斗室与Ⅳ号坦克歼击车类似，配备有性能良好的无线通讯装置，它的装甲防护与豹式坦克相同，正面是55度倾角、厚度为80mm的防护钢板，可以抵御苏军与盟军的中、重型坦克的正面攻击；它的火力比豹式坦克强大，所装的88mm火炮可以在1000m距离上击穿30度倾角的167mm装甲钢板；该车虽然重达46吨，但仍然保持有46km的车速，有较好的机动性；猎豹重型坦克歼击车是德军一种性能优越的自行反坦克炮车，该车装备德军后，在西线战场上有不俗的表现。但由于其投产时已是二战后期，生产数量有限，因此也难以起到影响战争进程的作用。</p><p>猎豹重型坦克歼击车前期使用的是黑豹A型车的底盘，到了1944年底，由于A型车底盘库存已用完，就改用了黑豹G型车的底盘。该车生产时间很短，但还是在生产过程中不断改进，该车可分为前期型和后期型（有资料还分出中期型），不过各型结构区别并不大。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_tankdestroyerjag_11.jpg","description":"<h6>“猎豹”重型坦克歼击车<br>型号：Jagdpanzer （Sdkfz 173）</h6><p>参数：车长：9.87m，车宽：3.42m，车高：2.71m，车重：45.5t；乘员：5人。</p><p>最高车速：46km/h，最大行程：160km；</p><p>装甲厚度：车体前部：60-80mm，车体两侧：40-50mm，车体后部：40mm，车体顶部：25mm，车体底部：16-25mm。</p><p>武器配备：1门Pak43型71倍口径88mm火炮；1挺MG34型7.92mm机枪；弹药配备：炮弹57发，机枪弹600发。</p>","caption":""},{"image":"{{text}}“猎豹”重型坦克歼击车前期型（1944年1月生产）四视图{{image}}imgs/de/army/de_army_tankdestroyerjag_12.jpg{{text}}“猎豹”重型坦克歼击车后期型四视图{{image}}imgs/de/army/de_army_tankdestroyerjag_13.jpg","description":"<p>相对初期型， 后期型在外形上辨别的特征是：</p><p><ol><li>后期型尾部的排气管加装了防护罩，以消除黑暗中排气管暴露的火光；同时在左侧排气管的两侧还加装了2个小排气管，以排出离合器和转向机构产生的热量。</li><li>后期型炮管改为双段式结构。</li><li>后期型火炮防盾由焊接式改为铆接式，防盾和车体的连接部分上下各加装了4个大螺栓。</p>","caption":""}],"part2title":"战场上的“猎豹”重型坦克歼击车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_tankdestroyerjag_21.jpg","description":"1944年7月法国诺曼底战场，德军654重坦克歼击营第2连的一辆“猎豹”重型坦克歼击车，从该车的二段式炮管可知是后期型的“猎豹”（以下同）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_22.jpg","description":"1944年8月法国诺曼底战场，德军654重坦克歼击营第3连编号332的一辆“猎豹”重型坦克歼击车（后期型）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_23.jpg","description":"1944年11月阿尔萨斯地区，德军654重坦克歼击营的一辆“猎豹”重型坦克歼击车（后期型）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_24.jpg","description":"1945年1月阿尔萨斯地区，德军654重坦克歼击营第3连编号314号的一辆“猎豹”重型坦克歼击车（前期型），该车已涂上了冬天的伪装色。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_25.jpg","description":"1945年1月阿尔萨斯地区在鲁尔包围圈，德军654重坦克歼击营第1连编号123号的一辆“猎豹”重型坦克歼击车（后期型）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_26.jpg","description":"1945年春天德国战场，德军一辆不明单位的“猎豹”重型坦克歼击车（后期型）。该车用树枝作了伪装，这种简易的伪装方法也在不少“猎豹”中使用。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_27.jpg","description":"1944年秋天，德军654重坦克歼击营第1连接收新交付的“猎豹”重型坦克歼击车。士兵们高兴地且坐在火炮上合影。654重坦克歼击营是最早装备“猎豹”重型坦克歼击车的德军反坦克部队，虽然“猎豹”数量一直配备不足，但在1944年的西线战场上对盟军仍造成很大的威胁。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_28.jpg","description":"1944年，隶属德军654重坦克歼击营第1连的一队“猎豹”重型坦克歼击车（前期型）正在向战场开进。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_29.jpg","description":"1944年8月法国诺曼底战场，一辆被盟军击毁的德军654重坦克歼击营编号为314的“猎豹”重型坦克歼击车（前期型），该车履带已完全脱落，盟军正准备将其拖引。在诺曼底战役中，德军虽然损失了不少“猎豹”，但还是有一定战绩的，其中7月底在诺曼底一次与盟军坦克部队遭遇战中，654重坦克歼击营的三辆“猎豹”以自损2辆的代价击毁了英军11辆丘吉尔坦克，有效阻止了英军的进攻。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_30.jpg","description":"1944年8月26日，在法国鲁昂渡口，一辆被盟军飞机炸毁的德军654重坦克歼击营第2连编号为201的“猎豹”重型坦克歼击车，该车炮管已完全折弯变形。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_31.jpg","description":"1944年8月下旬西线战场，德军654重坦克歼击营第3连正在向塞纳河撒退，为了避免受损战车落入快速挺进的盟军手中，行驶在最前面的一辆“猎豹”重型坦克歼击车正拖引着一辆已失去动力的“猎豹”行进。可能当时正在下雨，2名车组乘员还打着伞。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_32.jpg","description":"1944年9月2日，德军654重坦克歼击营从法国战场向德国境内撒退，图中是最早到达比利时斯珀的2辆“猎豹”重型坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_33.jpg","description":"1944年10月，德军654重坦克歼击营的装备的“猎豹”重型坦克歼击车编队（前期型与后期型混编）在集结中。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_34.jpg","description":"1944年11月底，在哈尔特森林附近，德军654重坦克歼击营的连长吕德斯上尉正在指引一辆“猎豹”重型坦克歼击车进入伏击阵地。在西线战场上，654重坦克歼击营与盟军展开了激烈的交锋，在1944年11月的战斗中，该营共击毁盟军52辆坦克，击伤9车坦克，击毁和击伤5辆装甲车和装甲运兵车，击毁10门反坦克炮，消灭1个步兵连。而该营自身一共有15辆“猎豹”重型坦克歼击车战损。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_35.jpg","description":"1944年11月28日，由于战场形势的变化，德军654重坦克歼击营第2连吕德斯战斗群正在转移阵地，这是转移途中的“猎豹”重型坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_36.jpg","description":"1945年1月，德国西线战场，德军654重坦克歼击营一辆被盟军击毁的“猎豹”重型坦克歼击车，该车是第3连连长施内普夫中尉（骑士十字勋章获得者）的坐车，施内普夫中尉也在战斗中死亡。在阿登反击战中，德军集结了6个营共50多辆“猎豹”与盟军激战，使盟军遭受了不少损失，在一辆已战死的“猎豹”车组成员的日记中，他所在的这辆“猎豹”在阿登丛林中的一个月作战中，一共击毁了美军谢尔曼坦克5辆，莹火虫坦克1辆，歼击车3辆，装甲车2辆，卡车13辆以及2支美军巡逻小队。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_37.jpg","description":"1945年1月30日，西线战场，一辆被盟军击毁的“猎豹”重型坦克歼击车，该车隶属德军654重坦克歼击营，编号不明，车长是许辛下士，有2名车组乘员在战斗中阵亡。图中远处是一辆自由法国部队的一辆已被击毁的谢尔曼坦克。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_38.jpg","description":"1945年1月30日，一辆被盟军击毁的“猎豹”重型坦克歼击车。该车隶属德军654重坦克歼击营第1连，编号101，这是一辆初期型的“猎豹”，一群自由法国部队的坦克兵正在检查这辆“猎豹”残骸。图中远处是自由法国部队的美制谢尔曼坦克和M10坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_39.jpg","description":"一辆被盟军击毁隶属德军654重坦克歼击营编号123的“猎豹”重型坦克歼击车，该车的前方几米远有一辆已被击毁美军M36坦克歼击车，可见两者的战斗已到了短兵相接的激烈程度了。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_40.jpg","description":"1945年3月13日，一辆被盟军击毁编号不明的“猎豹”重型坦克歼击车，该车是一辆后期型的“猎豹”，车体用树枝作了伪装。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_41.jpg","description":"1945年3月15日，一辆被德军遗弃的的“猎豹”重型坦克歼击车，该车一侧的主动轮已脱落，履带也断裂了。加拿大部队的研究人员正在对该辆“猎豹”进行认真研究。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerjag_42.jpg","description":"一名美军士兵正在一辆被击毁的“猎豹”重型坦克歼击车上检查，该车隶属654重型反坦克营，从防盾的4个螺栓可知这是一辆后期型的“猎豹”。","caption":""}]}')}});